import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/REPEATING-DATA.md","filePath":"manual-en/REPEATING-DATA.md","lastUpdated":1785684581000}'),i={name:"manual-en/REPEATING-DATA.md"};function s(r,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h3 id="_8-16-repeating-data" tabindex="-1">8.16 REPEATING DATA <a class="header-anchor" href="#_8-16-repeating-data" aria-label="Permalink to &quot;8.16 REPEATING DATA&quot;">​</a></h3><pre><code>REPEATING DATA
        /STARTS=start-end
        /OCCURS=n_occurs
        /FILE=’file_name’
        /LENGTH=length
        /CONTINUED[=cont_start-cont_end]
        /ID=id_start-id_end=id_var
        /{TABLE,NOTABLE}
        /DATA=var_spec…

where each var_spec takes one of the forms
        var_list start-end [type_spec]
        var_list (fortran_spec)
</code></pre><p><code>REPEATING DATA</code> parses groups of data repeating in a uniform format, possibly with several groups on a single line. Each group of data corresponds with one case. <code>REPEATING DATA</code> may only be used within an <code>INPUT PROGRAM</code> structure (see <a href="./INPUT-PROGRAM">INPUT PROGRAM</a>). When used with <code>DATA LIST</code>, it can be used to parse groups of cases that share a subset of variables but differ in their other data.</p><p>The <code>STARTS</code> subcommand is required. Specify a range of columns, using literal numbers or numeric variable names. This range specifies the columns on the first line that are used to contain groups of data. The ending column is optional. If it is not specified, then the record width of the input file is used. For the inline file (see <a href="./BEGIN-DATA">BEGIN DATA</a>) this is 80 columns; for a file with fixed record widths it is the record width; for other files it is 1024 characters by default.</p><p>The <code>OCCURS</code> subcommand is required. It must be a number or the name of a numeric variable. Its value is the number of groups present in the current record.</p><p>The <code>DATA</code> subcommand is required. It must be the last subcommand specified. It is used to specify the data present within each repeating group. Column numbers are specified relative to the beginning of a group at column 1. Data is specified in the same way as with <code>DATA LIST FIXED</code> (see <a href="./DATA-LIST-FIXED">DATA LIST FIXED</a>).</p><p>All other subcommands are optional.</p><p>FILE specifies the file to read, either a file name as a string or a file handle (see <a href="./File-Handles">File Handles</a>). If FILE is not present then the default is the last file handle used on <code>DATA LIST</code> (lexically, not in terms of flow of control).</p><p>By default <code>REPEATING DATA</code> will output a table describing how it will parse the input data. Specifying <code>NOTABLE</code> will disable this behavior; specifying TABLE will explicitly enable it.</p><p>The <code>LENGTH</code> subcommand specifies the length in characters of each group. If it is not present then length is inferred from the <code>DATA</code> subcommand. LENGTH can be a number or a variable name.</p><p>Normally all the data groups are expected to be present on a single line. Use the <code>CONTINUED</code> command to indicate that data can be continued onto additional lines. If data on continuation lines starts at the left margin and continues through the entire field width, no column specifications are necessary on <code>CONTINUED</code>. Otherwise, specify the possible range of columns in the same way as on STARTS.</p><p>When data groups are continued from line to line, it is easy for cases to get out of sync through careless hand editing. The <code>ID</code> subcommand allows a case identifier to be present on each line of repeating data groups. <code>REPEATING DATA</code> will check for the same identifier on each line and report mismatches. Specify the range of columns that the identifier will occupy, followed by an equals sign (‘=’) and the identifier variable name. The variable must already have been declared with <code>NUMERIC</code> or another command.</p><p><code>REPEATING DATA</code> should be the last command given within an <code>INPUT PROGRAM</code>. It should not be enclosed within a <code>LOOP</code> structure (see <a href="./LOOP">LOOP</a>). Use <code>DATA LIST</code> before, not after, <code>REPEATING DATA</code>.</p>`,13)])])}const f=a(i,[["render",s]]);export{u as __pageData,f as default};
